const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaDatabase, FaPlug, FaBook, FaShieldAlt, FaSearch, FaGitAlt, FaUsers, FaChartBar, FaLock, FaCog, FaRocket, FaKey, FaExclamationTriangle, FaCheckCircle, FaArrowRight, FaCode, FaFileAlt, FaTags, FaFolderOpen, FaLink, FaEye, FaTools, FaLightbulb, FaQuestion } = require("react-icons/fa");

// ── Palette ──
const C = {
  bg:       "0F172A",  // deep navy
  bgLight:  "1E293B",  // card background
  bgMid:    "334155",  // slightly lighter for contrast
  accent:   "F97316",  // orange
  accent2:  "06B6D4",  // cyan
  accent3:  "8B5CF6",  // purple
  accent4:  "10B981",  // green
  text:     "F8FAFC",  // near-white
  muted:    "94A3B8",  // gray
  dim:      "64748B",  // dimmer gray
  white:    "FFFFFF",
  red:      "EF4444",
  tableHead:"1E3A5F",
  tableRow1:"0F172A",
  tableRow2:"1A2744",
};

// ── Icon helper ──
function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToBase64Png(IconComponent, color = "#FFFFFF", size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// ── Shadow factory ──
const mkShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 45, opacity: 0.25 });

async function build() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Steven Noels";
  pres.title = "ctxlayer — Workshop";

  // Pre-render icons
  const icons = {
    database: await iconToBase64Png(FaDatabase, "#06B6D4"),
    plug:     await iconToBase64Png(FaPlug, "#F97316"),
    book:     await iconToBase64Png(FaBook, "#8B5CF6"),
    shield:   await iconToBase64Png(FaShieldAlt, "#10B981"),
    search:   await iconToBase64Png(FaSearch, "#06B6D4"),
    git:      await iconToBase64Png(FaGitAlt, "#F97316"),
    users:    await iconToBase64Png(FaUsers, "#94A3B8"),
    chart:    await iconToBase64Png(FaChartBar, "#10B981"),
    lock:     await iconToBase64Png(FaLock, "#EF4444"),
    cog:      await iconToBase64Png(FaCog, "#94A3B8"),
    rocket:   await iconToBase64Png(FaRocket, "#F97316"),
    key:      await iconToBase64Png(FaKey, "#F97316"),
    warning:  await iconToBase64Png(FaExclamationTriangle, "#EF4444"),
    check:    await iconToBase64Png(FaCheckCircle, "#10B981"),
    arrow:    await iconToBase64Png(FaArrowRight, "#F97316"),
    code:     await iconToBase64Png(FaCode, "#06B6D4"),
    file:     await iconToBase64Png(FaFileAlt, "#94A3B8"),
    tags:     await iconToBase64Png(FaTags, "#8B5CF6"),
    folder:   await iconToBase64Png(FaFolderOpen, "#F97316"),
    link:     await iconToBase64Png(FaLink, "#06B6D4"),
    eye:      await iconToBase64Png(FaEye, "#10B981"),
    tools:    await iconToBase64Png(FaTools, "#F97316"),
    lightbulb:await iconToBase64Png(FaLightbulb, "#F97316"),
    question: await iconToBase64Png(FaQuestion, "#94A3B8"),
    checkW:   await iconToBase64Png(FaCheckCircle, "#FFFFFF"),
    warningW: await iconToBase64Png(FaExclamationTriangle, "#FFFFFF"),
    plugW:    await iconToBase64Png(FaPlug, "#FFFFFF"),
    bookW:    await iconToBase64Png(FaBook, "#FFFFFF"),
    shieldW:  await iconToBase64Png(FaShieldAlt, "#FFFFFF"),
    databaseW:await iconToBase64Png(FaDatabase, "#FFFFFF"),
  };

  // ════════════════════════════════════════
  // SLIDE 1 — Title
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    // Large title
    s.addText("ctxlayer", {
      x: 0.8, y: 1.2, w: 8.4, h: 1.2,
      fontSize: 56, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });
    s.addText("Your team's shared context layer", {
      x: 0.8, y: 2.3, w: 8.4, h: 0.6,
      fontSize: 24, fontFace: "Calibri", color: C.accent, margin: 0,
    });
    s.addText("yukitools.dev  ·  Workshop", {
      x: 0.8, y: 3.2, w: 8.4, h: 0.5,
      fontSize: 16, fontFace: "Calibri", color: C.muted, margin: 0,
    });
    // Four small icons bottom right
    s.addImage({ data: icons.database, x: 6.5, y: 4.2, w: 0.5, h: 0.5 });
    s.addImage({ data: icons.plug, x: 7.2, y: 4.2, w: 0.5, h: 0.5 });
    s.addImage({ data: icons.book, x: 7.9, y: 4.2, w: 0.5, h: 0.5 });
    s.addImage({ data: icons.shield, x: 8.6, y: 4.2, w: 0.5, h: 0.5 });
    s.addNotes("Welcome to the ctxlayer workshop. This presentation covers the main concepts of ctxlayer and how to use it as a practitioner or admin on the yukitools.dev deployment.");
  }

  // ════════════════════════════════════════
  // SLIDE 2 — The problem: individual connections
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("The MCP landscape today", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });
    s.addText("Every developer manages their own connections", {
      x: 0.8, y: 0.95, w: 8.4, h: 0.4,
      fontSize: 16, fontFace: "Calibri", color: C.accent, margin: 0,
    });

    // Diagram: 4 users on the left, 4 services on the right, chaotic lines between them
    const userNames = ["Alice", "Bob", "Carol", "Dave"];
    const serviceNames = ["ADO", "Notion", "Driver", "Yuki IA"];
    const userX = 1.0, serviceX = 7.5;
    const startY = 1.7, gap = 0.85;

    // User boxes
    for (let i = 0; i < 4; i++) {
      const y = startY + i * gap;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: userX, y, w: 1.5, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08, shadow: mkShadow(),
      });
      s.addText(userNames[i], {
        x: userX, y, w: 1.5, h: 0.55,
        fontSize: 13, fontFace: "Calibri", color: C.text, align: "center", valign: "middle", margin: 0,
      });
    }

    // Service boxes
    for (let i = 0; i < 4; i++) {
      const y = startY + i * gap;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: serviceX, y, w: 1.5, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08, shadow: mkShadow(),
      });
      s.addText(serviceNames[i], {
        x: serviceX, y, w: 1.5, h: 0.55,
        fontSize: 13, fontFace: "Calibri", color: C.accent, align: "center", valign: "middle", margin: 0,
      });
    }

    // Chaotic lines — each user connects to multiple services
    const connections = [
      [0,0],[0,1],[0,2],[0,3],
      [1,0],[1,1],[1,3],
      [2,0],[2,2],[2,3],
      [3,0],[3,1],[3,2],
    ];
    const lineColors = [C.red, C.accent, C.accent2, C.accent3, C.accent4, C.muted];
    connections.forEach((conn, idx) => {
      const y1 = startY + conn[0] * gap + 0.275;
      const y2 = startY + conn[1] * gap + 0.275;
      const x1 = userX + 1.5;
      const x2 = serviceX;
      // Draw angled line using LINE shape
      s.addShape(pres.shapes.LINE, {
        x: x1, y: Math.min(y1, y2), w: x2 - x1, h: Math.abs(y2 - y1) * (y2 >= y1 ? 1 : 1),
        line: { color: lineColors[idx % lineColors.length], width: 1.2, dashType: "dash" },
        flipV: y2 < y1,
      });
    });

    // "N×M" label
    s.addText("4 users × 4 services = 16 connections", {
      x: 2.8, y: 4.6, w: 4.4, h: 0.4,
      fontSize: 14, fontFace: "Calibri", color: C.red, align: "center", margin: 0, bold: true,
    });

    s.addNotes("Each person has to configure MCP servers locally — claude_desktop_config.json, .mcp.json, managed-mcp.json. Credentials live in local files. No shared knowledge. No visibility into tool usage. Onboarding = 'copy my config and change the tokens'.");
  }

  // ════════════════════════════════════════
  // SLIDE 3 — What goes wrong
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("What goes wrong", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });

    const problems = [
      { icon: icons.key, title: "Token rotation", desc: "Everyone has to update their local config" },
      { icon: icons.warning, title: "New upstream", desc: "Someone Slacks the setup — half the team misses it" },
      { icon: icons.search, title: "No org context", desc: "Agent asks 'which ADO project?' every single time" },
      { icon: icons.lock, title: "No guardrails", desc: "Any tool is callable, no conventions enforced" },
      { icon: icons.eye, title: "Zero visibility", desc: "Are people using the Notion integration? No idea" },
    ];

    problems.forEach((p, i) => {
      const y = 1.3 + i * 0.82;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: 1.0, y, w: 8.0, h: 0.65, fill: { color: C.bgLight }, rectRadius: 0.08,
      });
      s.addImage({ data: p.icon, x: 1.2, y: y + 0.1, w: 0.42, h: 0.42 });
      s.addText(p.title, {
        x: 1.8, y, w: 2.2, h: 0.65,
        fontSize: 14, fontFace: "Calibri", bold: true, color: C.text, valign: "middle", margin: 0,
      });
      s.addText(p.desc, {
        x: 4.0, y, w: 4.8, h: 0.65,
        fontSize: 13, fontFace: "Calibri", color: C.muted, valign: "middle", margin: 0,
      });
    });

    s.addNotes("These pain points compound at scale. Token rotation becomes a fire drill. New services are adopted unevenly. The agent has no memory of your org's conventions.");
  }

  // ════════════════════════════════════════
  // SLIDE 4 — The solution: hub and spoke
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("One connection, full context", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });

    // Hub: ctxlayer in the center
    const hubX = 3.8, hubY = 2.1, hubW = 2.4, hubH = 1.2;
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: hubX, y: hubY, w: hubW, h: hubH, fill: { color: C.accent }, rectRadius: 0.15, shadow: mkShadow(),
    });
    s.addText("ctxlayer", {
      x: hubX, y: hubY, w: hubW, h: hubH * 0.55,
      fontSize: 22, fontFace: "Calibri", bold: true, color: C.bg, align: "center", valign: "bottom", margin: 0,
    });
    s.addText("yukitools.dev", {
      x: hubX, y: hubY + hubH * 0.5, w: hubW, h: hubH * 0.5,
      fontSize: 11, fontFace: "Calibri", color: C.bg, align: "center", valign: "top", margin: 0,
    });

    // Left: users
    const clients = ["Claude Code", "Claude Desktop", "Cursor"];
    clients.forEach((name, i) => {
      const y = 1.7 + i * 0.9;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: 0.5, y, w: 1.8, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08,
      });
      s.addText(name, {
        x: 0.5, y, w: 1.8, h: 0.55,
        fontSize: 12, fontFace: "Calibri", color: C.text, align: "center", valign: "middle", margin: 0,
      });
      // Arrow to hub
      s.addShape(pres.shapes.LINE, {
        x: 2.3, y: y + 0.275, w: 1.5, h: 0,
        line: { color: C.accent4, width: 2 },
      });
    });

    // Right: upstreams
    const upstreams = [
      { name: "ADO", tools: "37 tools" },
      { name: "Notion", tools: "18 tools" },
      { name: "Driver", tools: "14 tools" },
      { name: "Yuki IA", tools: "12 tools" },
    ];
    upstreams.forEach((u, i) => {
      const y = 1.3 + i * 0.82;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: 7.5, y, w: 2.0, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08,
      });
      s.addText([
        { text: u.name, options: { bold: true, color: C.accent, fontSize: 12 } },
        { text: `  ${u.tools}`, options: { color: C.muted, fontSize: 10 } },
      ], {
        x: 7.5, y, w: 2.0, h: 0.55,
        fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
      });
      // Arrow from hub
      s.addShape(pres.shapes.LINE, {
        x: 6.2, y: hubY + hubH / 2, w: 1.3, h: (y + 0.275) - (hubY + hubH / 2),
        line: { color: C.accent2, width: 2 },
        flipV: (y + 0.275) < (hubY + hubH / 2),
      });
    });

    // Bottom: docs + skills
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 2.8, y: 3.8, w: 1.8, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08,
    });
    s.addImage({ data: icons.database, x: 2.95, y: 3.88, w: 0.35, h: 0.35 });
    s.addText("Docs + RAG", {
      x: 3.35, y: 3.8, w: 1.2, h: 0.55,
      fontSize: 11, fontFace: "Calibri", color: C.accent2, valign: "middle", margin: 0,
    });

    s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 5.2, y: 3.8, w: 1.8, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08,
    });
    s.addImage({ data: icons.book, x: 5.35, y: 3.88, w: 0.35, h: 0.35 });
    s.addText("Skills", {
      x: 5.75, y: 3.8, w: 1.2, h: 0.55,
      fontSize: 11, fontFace: "Calibri", color: C.accent3, valign: "middle", margin: 0,
    });

    // Key message
    s.addText("You configure ONE MCP connection. ctxlayer handles the rest.", {
      x: 1.5, y: 4.7, w: 7.0, h: 0.5,
      fontSize: 16, fontFace: "Calibri", bold: true, color: C.accent, align: "center", margin: 0,
    });

    s.addNotes("This is the core idea: instead of N users × M services connections, everyone connects to ctxlayer once. ctxlayer fans out to all upstream MCP servers, provides the shared doc library, and serves curated skills.");
  }

  // ════════════════════════════════════════
  // SLIDE 5 — Four pillars
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("What ctxlayer gives you", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });

    const pillars = [
      { icon: icons.database, color: C.accent2, title: "Context Docs", line1: "Shared org knowledge", line2: "the agent can search", example: '"What\'s our Peppol spec?" → agent finds it' },
      { icon: icons.plug, color: C.accent, title: "Upstreams", line1: "Proxied MCP servers", line2: "centralised credentials", example: "81 tools, 4 services, one connection" },
      { icon: icons.book, color: C.accent3, title: "Skills", line1: "Procedural playbooks", line2: 'for "how we do X"', example: '"Triage a failed build" → recipe' },
      { icon: icons.shield, color: C.accent4, title: "Governance", line1: "Visibility, access control,", line2: "usage analytics", example: "Admin sees who calls what" },
    ];

    pillars.forEach((p, i) => {
      const x = 0.5 + i * 2.35;
      const w = 2.15;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x, y: 1.3, w, h: 3.5, fill: { color: C.bgLight }, rectRadius: 0.12, shadow: mkShadow(),
      });
      // Icon in colored circle
      s.addShape(pres.shapes.OVAL, {
        x: x + (w - 0.7) / 2, y: 1.55, w: 0.7, h: 0.7, fill: { color: p.color, transparency: 20 },
      });
      s.addImage({ data: p.icon, x: x + (w - 0.45) / 2, y: 1.68, w: 0.45, h: 0.45 });
      // Title
      s.addText(p.title, {
        x, y: 2.45, w, h: 0.5,
        fontSize: 16, fontFace: "Calibri", bold: true, color: C.text, align: "center", margin: 0,
      });
      // Description
      s.addText([
        { text: p.line1, options: { breakLine: true } },
        { text: p.line2 },
      ], {
        x: x + 0.1, y: 3.0, w: w - 0.2, h: 0.7,
        fontSize: 12, fontFace: "Calibri", color: C.muted, align: "center", margin: 0,
      });
      // Example
      s.addText(p.example, {
        x: x + 0.1, y: 3.8, w: w - 0.2, h: 0.7,
        fontSize: 11, fontFace: "Calibri", italic: true, color: p.color, align: "center", margin: 0,
      });
    });

    s.addNotes("These four pillars work together: docs give the agent background knowledge, upstreams give it tools, skills tell it how to use those tools, and governance gives admins control and visibility.");
  }

  // ════════════════════════════════════════
  // SLIDE 6 — Section: Context Docs
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addImage({ data: icons.database, x: 4.3, y: 1.5, w: 1.4, h: 1.4 });
    s.addText("Context Docs", {
      x: 0.8, y: 3.0, w: 8.4, h: 0.8,
      fontSize: 44, fontFace: "Calibri", bold: true, color: C.text, align: "center", margin: 0,
    });
    s.addText("The org's shared knowledge base", {
      x: 0.8, y: 3.8, w: 8.4, h: 0.5,
      fontSize: 18, fontFace: "Calibri", color: C.accent2, align: "center", margin: 0,
    });
    s.addNotes("Section divider: Context Docs — what the agent knows about your org.");
  }

  // ════════════════════════════════════════
  // SLIDE 7 — Two ways docs get in
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("How docs get into ctxlayer", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });

    // Left card: Write
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 0.5, y: 1.3, w: 4.3, h: 3.5, fill: { color: C.bgLight }, rectRadius: 0.12, shadow: mkShadow(),
    });
    s.addImage({ data: icons.file, x: 0.8, y: 1.55, w: 0.45, h: 0.45 });
    s.addText("Write in ctxlayer", {
      x: 1.4, y: 1.55, w: 3.2, h: 0.45,
      fontSize: 18, fontFace: "Calibri", bold: true, color: C.accent2, valign: "middle", margin: 0,
    });
    s.addText([
      { text: "Collaborative editor", options: { bullet: true, breakLine: true, fontSize: 13, color: C.text } },
      { text: "Notion-style block editing", options: { bullet: true, breakLine: true, fontSize: 13, color: C.muted } },
      { text: "Real-time co-editing (Yjs)", options: { bullet: true, breakLine: true, fontSize: 13, color: C.muted } },
      { text: "Auto-save + revision history", options: { bullet: true, breakLine: true, fontSize: 13, color: C.muted } },
      { text: "Folders + tags for organisation", options: { bullet: true, fontSize: 13, color: C.muted } },
    ], {
      x: 0.8, y: 2.2, w: 3.8, h: 2.4,
      fontFace: "Calibri", margin: 0,
    });

    // Right card: Git sync
    s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 5.2, y: 1.3, w: 4.3, h: 3.5, fill: { color: C.bgLight }, rectRadius: 0.12, shadow: mkShadow(),
    });
    s.addImage({ data: icons.git, x: 5.5, y: 1.55, w: 0.45, h: 0.45 });
    s.addText("Sync from Git", {
      x: 6.1, y: 1.55, w: 3.2, h: 0.45,
      fontSize: 18, fontFace: "Calibri", bold: true, color: C.accent, valign: "middle", margin: 0,
    });
    s.addText([
      { text: "Connect a repo (GitHub / GitLab / ADO)", options: { bullet: true, breakLine: true, fontSize: 13, color: C.text } },
      { text: "Set a path filter (docs/**/*.md)", options: { bullet: true, breakLine: true, fontSize: 13, color: C.muted } },
      { text: "Scheduled cron sync", options: { bullet: true, breakLine: true, fontSize: 13, color: C.muted } },
      { text: "Edits can be proposed back as PRs", options: { bullet: true, breakLine: true, fontSize: 13, color: C.muted } },
      { text: "Conflict detection built in", options: { bullet: true, fontSize: 13, color: C.muted } },
    ], {
      x: 5.5, y: 2.2, w: 3.8, h: 2.4,
      fontFace: "Calibri", margin: 0,
    });

    s.addNotes("Docs come in two ways: authored in the collaborative editor (like Notion) or synced from git repos. Both end up in the same searchable library. Git sync supports GitHub, GitLab, and Azure DevOps.");
  }

  // ════════════════════════════════════════
  // SLIDE 8 — RAG search flow
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("How docs reach the agent", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });
    s.addText("RAG-powered semantic search", {
      x: 0.8, y: 0.95, w: 8.4, h: 0.4,
      fontSize: 16, fontFace: "Calibri", color: C.accent2, margin: 0,
    });

    // Flow: 4 steps left-to-right
    const steps = [
      { label: "Doc saved", sub: "chunked +\nembedded", color: C.accent2 },
      { label: "search_docs()", sub: '"Peppol\ne-invoicing"', color: C.accent },
